CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, status text NOT NULL DEFAULT 'disconnected' CHECK (status IN ('disconnected','connecting','qr','connected','logged_out','failed')), phone text, last_connected_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,name));
CREATE INDEX IF NOT EXISTS sessions_owner_idx ON sessions(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS api_keys (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id uuid REFERENCES sessions(id) ON DELETE CASCADE, name text NOT NULL, key_hash text NOT NULL UNIQUE, prefix text NOT NULL, permissions text[] NOT NULL DEFAULT ARRAY['messages:send'], created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz, revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS api_keys_owner_idx ON api_keys(user_id);
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, provider_message_id text, idempotency_key text, to_number text NOT NULL, type text NOT NULL, body text, status text NOT NULL CHECK(status IN ('queued','sending','sent','delivered','read','failed','unknown')), error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,idempotency_key));
CREATE INDEX IF NOT EXISTS messages_owner_idx ON messages(user_id, created_at DESC);
CREATE TABLE IF NOT EXISTS webhooks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, url text NOT NULL, secret_hash text NOT NULL, events text[] NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE TABLE IF NOT EXISTS webhook_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), webhook_id uuid NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE, event_id uuid NOT NULL, status text NOT NULL, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_id text, ip inet, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_records (id bigserial PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, quantity integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS application_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
